WITH cleaned AS (SELECT *, CAST(event_time AS DATE) event_time_day, COALESCE(page, 'NONE') page_clean FROM web_events WHERE event_time > TO_TIMESTAMP('2023-03-19 08:00:00') AND page IS NOT NULL) SELECT p.browser, e.event_type, COUNT(*) AS num_rows, MAX(e.duration_sec) AS max_duration_sec FROM cleaned e INNER JOIN sessions p ON e.session_id = p.id GROUP BY GROUPING SETS ((p.browser, e.event_type), (p.browser), ());
